if (inventory_count('wheat_seeds') < 1) {
  return { done: false, detail: 'no seeds to plant' };
}
const ground = find_block({ names: ['grass_block', 'dirt', 'farmland'], max_distance: 8 });
if (!ground) {
  return { done: false, detail: 'no ground to plant on' };
}
const put = await place('wheat_seeds', ground.x, ground.y + 1, ground.z);
if (!put.ok) {
  return { done: false, detail: put.detail };
}
return { done: true, detail: 'planted a seed' };
